template.script:
(function(){
  // FAQ
  document.querySelectorAll('.ipp__faq-q').forEach(function(b){b.addEventListener('click',function(){var it=this.closest('.ipp__faq-item'),o=it.classList.contains('open');document.querySelectorAll('.ipp__faq-item').forEach(function(i){i.classList.remove('open')});if(!o)it.classList.add('open');});});
  // Modales
  function openM(id){var o=document.getElementById('modal-'+id);if(!o)return;o.classList.add('open');document.body.style.overflow='hidden';o.querySelector('.ipp__modal').scrollTop=0;}
  function closeM(o){o.classList.remove('open');document.body.style.overflow='';}
  document.querySelectorAll('[data-modal]').forEach(function(b){b.addEventListener('click',function(){openM(this.getAttribute('data-modal'));});});
  document.querySelectorAll('.ipp__modal-close').forEach(function(b){b.addEventListener('click',function(){closeM(this.closest('.ipp__modal-overlay'));});});
  document.querySelectorAll('.ipp__modal-overlay').forEach(function(o){o.addEventListener('click',function(e){if(e.target===o)closeM(o);});});
  document.addEventListener('keydown',function(e){if(e.key==='Escape')document.querySelectorAll('.ipp__modal-overlay.open').forEach(closeM);});
  // Videos
  document.querySelectorAll('.ipp__video-card').forEach(function(c){c.addEventListener('click',function(){document.getElementById('ipp-video-frame').src='https://www.youtube.com/embed/'+this.dataset.vid+'?autoplay=1&rel=0';document.getElementById('ipp-video-lb').style.display='flex';});});
  document.getElementById('ipp-video-lb').addEventListener('click',function(e){if(e.target===this){this.style.display='none';document.getElementById('ipp-video-frame').src='';}});
  // IntersectionObserver para animaciones
  if('IntersectionObserver' in window){var obs=new IntersectionObserver(function(e){e.forEach(function(x){if(x.isIntersecting){x.target.style.animationPlayState='running';obs.unobserve(x.target);}});},{threshold:.12});document.querySelectorAll('.ipp__anim').forEach(function(el){if(!el.closest('.ipp__hero')){el.style.animationPlayState='paused';obs.observe(el);}});}
  // Counters
  function cnt(el,t,s){var n=0,st=Math.ceil(t/(1800/16));var i=setInterval(function(){n+=st;if(n>=t){n=t;clearInterval(i);}el.textContent=(n>=1000000?(n/1000000).toFixed(0)+'M':n)+s;},16);}
  var nums=document.querySelector('.ipp__numeros'),cRun=false;
  if(nums&&'IntersectionObserver' in window){new IntersectionObserver(function(e){if(e[0].isIntersecting&&!cRun){cRun=true;var d=[{el:nums.querySelectorAll('strong')[0],v:15,s:'+'},{el:nums.querySelectorAll('strong')[1],v:3,s:''},{el:nums.querySelectorAll('strong')[2],v:25,s:'M+'},{el:nums.querySelectorAll('strong')[3],v:100,s:'%'}];d.forEach(function(x){if(x.el)cnt(x.el,x.v,x.s);});}},{threshold:.3}).observe(nums);}
  // Smooth scroll
  document.querySelectorAll('a[href^="#"]').forEach(function(a){a.addEventListener('click',function(e){var h=this.getAttribute('href');if(!h||h==='#')return;var t=document.querySelector(h);if(t){e.preventDefault();t.scrollIntoView({behavior:'smooth',block:'start'});}});});
})();

